import{z as A,x as B,o,c as d,q as i,j as r,D as t,d as n,s,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Induction Heads 归纳头","description":"","frontmatter":{"title":"Induction Heads 归纳头","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/induction-heads.md","filePath":"llm/induction-heads.md","lastUpdated":1791063341000}'),c={name:"llm/induction-heads.md"};function h(p,e,D,m,u,f){const E=B("Mermaid");return o(),d("div",null,[e[2]||(e[2]=i('<h1 id="induction-heads-归纳头" tabindex="-1">Induction Heads 归纳头 <a class="header-anchor" href="#induction-heads-归纳头" aria-label="Permalink to &quot;Induction Heads 归纳头&quot;">​</a></h1><div class="epigraph"><p>归纳头实现一种简单算法：补全形如 [A][B] … [A] → [B] 的 token 序列。我们给出初步证据，说明它们可能构成大 Transformer 里大部分上下文学习（损失随 token 位置下降）的机制来源。</p><footer>—— Olsson et al., In-context Learning and Induction Heads, Anthropic 2022</footer></div><p>归纳头（induction heads）是一类注意力头，专门做「刚才见过的模式再来一次」：当前 token 是 \\(A\\)，就去找上一次 \\(A\\) 后面跟着的 \\(B\\)，然后提高 \\(B\\) 的 logits。Olsson、Elhage、Nanda、Olah 等人 2022 年 3 月的 transformer-circuits 长文（arXiv:2209.11895）把这种头从两层注意力模型里的电路，外推成一般 in-context learning 的候选机制。他们给出六条互补证据：小模型上有因果，大模型上主要是相关；归纳头形成的时刻与训练损失上「上下文学习突然变好」的拐点重合。本篇写电路本身、它与 few-shot 的关系，以及假说在带 MLP 的大模型上变弱的那一段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPT 一类模型不必更新权重就能利用提示里的例子，Brown 等人称之为 in-context learning。行为描述不等于机制。可能的实现有很多：把例子当检索库、把任务向量写进残差、或只是短程 n-gram 统计。需要一种可在权重里指认的算法，它在序列位置变长时降低损失，并且能被因果干预关掉。</p><p>最简可检验的算法是精确复制：<code>[A][B] … [A]</code> 预测 <code>B</code>。若某种头专门做这件事，就可以在注意力图、组成电路和消融上抓住它。再问第二句：这种头是否也做模糊匹配——<code>A*</code> 像 \\(A\\)、\\(B*\\) 像 \\(B\\) 时仍能补全——从而承担更一般的 few-shot，而不只是抄 token。</p><h3 id="两层注意力已经够写完最小电路" tabindex="-1">两层注意力已经够写完最小电路 <a class="header-anchor" href="#两层注意力已经够写完最小电路" aria-label="Permalink to &quot;两层注意力已经够写完最小电路&quot;">​</a></h3><p>一层注意力很难同时「知道自己的前一个 token 是谁」和「去远距离找上一次相同 token」。标准故事是两条头分工。前一 token 头（previous-token head）把「我前面是 \\(A\\)」写进 \\(B\\) 的位置；归纳头在后一层用当前 \\(A\\) 去匹配那些被写过「前面是 \\(A\\)」的位置，于是对齐到上一次的 \\(B\\)，再把 \\(B\\) 的值拷过来。Elhage 等人 2021 年的 <em>A Mathematical Framework for Transformer Circuits</em> 提供了 QK/OV 分解语言；Olsson 这篇把该语言用在归纳算法上。<span class="marginnote">「头」是注意力的一条输出通道，不是一个神经元。归纳性是对 QK 模式与 OV 拷贝的描述，同一头还可以兼做别的。用平均注意力图上「看起来像归纳」来点名，必须补一条因果：敲掉它，<code>[A][B]…[A]→[B]</code> 是否变差。</span><span class="marginnote">可以把这两层想象成两个人分工：前一 token 头像贴便利贴的，在每个字后面贴一张写着「我前面是 X」的纸条；归纳头像找便利贴的，拿着当前的 A 去翻所有纸条，找到写着「我前面是 A」的那张，再看它后面那个字是什么，抄过来当答案。单层注意力要一个人同时贴又找，所以很难。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在两层、仅注意力的模型里，可以画完电路并做激活修补：把归纳头的输出换成对照运行的输出，精确复制任务应崩溃。证据清单还包括：归纳头在训练中突然出现，与上下文学习能力的相变同一窗口；在更大模型里，具有归纳注意模式的头与 in-context 损失相关；扰动这些头伤害的是依赖上下文的那部分损失，而不是零样本的静态知识；把序列打乱使归纳线索失效时，相关头的贡献下降。大模型带 MLP，无法像两层模型那样做完备的电路证明，作者明确把那部分标成相关证据。</p> \\[\\text{当前 }A\\ \\xrightarrow{\\text{QK 匹配「曾以 }A\\text{ 为前缀」的位置}}\\ \\text{取其 OV 中的 }B \\]<p>模糊版把 \\(A\\) 换成近邻 \\(A^*\\)，匹配发生在某种相似性空间而不是 token 相等。这是从精确复制走向 few-shot 类比的跳板，也是大模型假说里最难严格验证的一步。<span class="marginnote">「模糊匹配」翻译成大白话：当前 token 不必和之前的一模一样，只要够像。比如 few-shot 例子里给过「猫 → 喵」，现在题目出现「犬」，归纳头在相似性空间里认出「这跟猫差不多」，就把例子里输出位置的「喵」当模板抄过来。例子之间很少逐字重复，few-shot 能用起来靠的就是这一步从「抄 token」升级成「抄格式」。</span></p><h3 id="六条证据不是六次重复" tabindex="-1">六条证据不是六次重复 <a class="header-anchor" href="#六条证据不是六次重复" aria-label="Permalink to &quot;六条证据不是六次重复&quot;">​</a></h3><p>时间重合、小模型因果、大模型相关、扰动、模式补全、以及与框架级电路分析的一致性，各自排除一种替代解释。例如「只是头变强了」解释不了为什么拐点与归纳模式同时出现；「只是注意力变尖」解释不了 OV 必须拷贝后继 token。读者应把清单当联合论证，而不是只引用注意力可视化那一张图。可视化既不能区分拷贝与匹配，也看不到 <a href="/llm/superposition-hypothesis">叠加</a> 下方向的混合。</p>',14)),(o(),r(l,null,{default:t(()=>[s(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BD%8D%E7%BD%AE%20t-1%3A%20token%20A%22%5D%20--%3E%20PTH%5B%22%E5%89%8D%E4%B8%80%20token%20%E5%A4%B4%22%5D%0A%20%20T2%5B%22%E4%BD%8D%E7%BD%AE%20t%3A%20token%20B%22%5D%20--%3E%20PTH%0A%20%20PTH%20--%3E%20MEM%5B%22B%20%E5%A4%84%E5%86%99%E5%85%A5%E3%80%8C%E5%89%8D%E7%BC%80%E6%98%AF%20A%E3%80%8D%22%5D%0A%20%20T3%5B%22%E5%90%8E%E9%9D%A2%E5%86%8D%E6%AC%A1%E5%87%BA%E7%8E%B0%20A%22%5D%20--%3E%20IH%5B%22%E5%BD%92%E7%BA%B3%E5%A4%B4%20QK%22%5D%0A%20%20MEM%20--%3E%20IH%0A%20%20IH%20--%3E%20CPY%5B%22OV%20%E6%8B%B7%E8%B4%9D%20B%22%5D%0A%20%20CPY%20--%3E%20LOGIT%5B%22%E6%8F%90%E9%AB%98%20B%20%E7%9A%84%20logits%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("h3",{id:"qk-匹配与-ov-拷贝缺一不可",tabindex:"-1"},[n("QK 匹配与 OV 拷贝缺一不可 "),a("a",{class:"header-anchor",href:"#qk-匹配与-ov-拷贝缺一不可","aria-label":'Permalink to "QK 匹配与 OV 拷贝缺一不可"'},"​")],-1)),e[5]||(e[5]=a("p",null,"QK 电路负责「去哪看」：归纳头的查询来自当前 \\(A\\)，键来自被前一 token 头标记过的位置。OV 电路负责「看完写什么」：值应接近 \\(B\\) 的嵌入或残差，才能在解嵌处抬高 \\(B\\)。两条缺一不可。只有 QK 像归纳、OV 在写别的东西，则只是检索头；只有 OV 能拷贝、QK 乱看，则是盲目复制。完整归纳头是匹配加拷贝。",-1)),(o(),r(l,null,{default:t(()=>[s(E,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20A1%5B%22%E9%85%8D%E7%BD%AE%E4%B8%80%3A%20%E5%8F%AA%E6%9C%89%20QK%20%E5%83%8F%E5%BD%92%E7%BA%B3%22%5D%20--%3E%20R1%5B%22%E5%8F%AA%E6%98%AF%E6%A3%80%E7%B4%A2%E5%A4%B4%3A%20%E7%9C%8B%E5%AF%B9%E4%BA%86%E4%BD%8D%E7%BD%AE%3Cbr%2F%3E%E4%BD%86%E5%8F%96%E5%9B%9E%E7%9A%84%E5%86%85%E5%AE%B9%E6%97%A0%E7%94%A8%22%5D%0A%20%20A2%5B%22%E9%85%8D%E7%BD%AE%E4%BA%8C%3A%20%E5%8F%AA%E6%9C%89%20OV%20%E4%BC%9A%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20R2%5B%22%E7%9B%B2%E7%9B%AE%E5%A4%8D%E5%88%B6%3A%20%E6%8B%B7%E8%B4%9D%E8%83%BD%E5%8A%9B%E5%BE%88%E5%BC%BA%3Cbr%2F%3E%E4%BD%86%E7%9C%8B%E7%9A%84%E5%85%A8%E6%98%AF%E6%97%A0%E5%85%B3%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20A3%5B%22%E9%85%8D%E7%BD%AE%E4%B8%89%3A%20QK%20%E5%8C%B9%E9%85%8D%20%2B%20OV%20%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20R3%5B%22%E5%AE%8C%E6%95%B4%E5%BD%92%E7%BA%B3%E5%A4%B4%3Cbr%2F%3E%5BA%5D%5BB%5D%E2%80%A6%5BA%5D%20%E5%90%8E%E9%A2%84%E6%B5%8B%20B%22%5D%0A%20%20R1%20-.%E6%B6%88%E8%9E%8D%E5%AE%9E%E9%AA%8C.-%20R3%0A%20%20R2%20-.%E6%B6%88%E8%9E%8D%E5%AE%9E%E9%AA%8C.-%20R3%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p>与 in-context learning 的桥梁是：few-shot 例子可看成许多 <code>[输入模式][输出模式]</code> 对。若归纳电路能在相似性空间里匹配模式，而不是只匹配表面 token，它就能把「上一个例子的输出格式」拷到当前题。这解释了为什么 ICL 随上下文长度变好——更多先前出现的 <code>[A][B]</code> 可供匹配——也解释了为什么打乱例子顺序或破坏间隔会伤成绩。它不自动解释需要多步推理的 ICL；那些可能要 MLP 与更深电路。</p><p>与 in-context learning 的桥梁是：few-shot 例子可看成许多 <code>[输入模式][输出模式]</code> 对。若归纳电路能在相似性空间里匹配模式，而不是只匹配表面 token，它就能把「上一个例子的输出格式」拷到当前题。这解释了为什么 ICL 随上下文长度变好——更多先前出现的 <code>[A][B]</code> 可供匹配——也解释了为什么打乱例子顺序或破坏间隔会伤成绩。它不自动解释需要多步推理的 ICL；那些可能要 MLP 与更深电路。</p><p><span class="marginnote">训练损失里随位置下降的那一部分，论文当作 ICL 的操作定义。这比「会做 few-shot 分类」更宽：包含简单的重复抄写。因此「归纳头解释大部分 ICL」中的 ICL 是这个宽定义。若把 ICL 理解成只含指令归纳与抽象类比，证据强度应下调到「必要组件，未必充分」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>小模型因果强、大模型相关弱，这是作者自己的分层。MLP、多层残差、<a href="/llm/superposition-hypothesis">叠加</a> 都会让「一个头 = 一个算法」失效：归纳计算可能散在若干头与 MLP 特征上。后来的工作指出功能向量、任务向量与归纳头相互作用，归纳头不是 ICL 的全部。敲掉所有看起来像归纳的头，模型仍会保留部分上下文敏感行为。</p><p>工程上，归纳头依赖 KV 里真的存着上一次 \\(A\\) 与 \\(B\\)。超长上下文、稀疏注意力、KV 压缩若丢掉「上一次出现」的键，复制电路会静默失败。这与 <a href="/llm/cost-per-mtok">百万 token 成本</a> 无关，却与缓存驱逐有关：被丢掉的不是任意 token，可能是归纳匹配所需要的那一次出现。解释行为退化时，应先查是否还留着可匹配的前缀，再查权重是否坏了。<span class="marginnote">常见误区：以为敲掉所有「看起来像归纳」的头，模型就彻底不会上下文学习。实际上大模型里这类计算往往分散在多个头和 MLP 特征上，消融之后仍会残留一部分上下文敏感行为。所以论文的措辞是「大部分 ICL 的候选机制来源」，而不是唯一来源——把它当成必要组件，比当成充分解释更稳。</span></p><p><span class="marginnote">不要把注意力图上的「对角线 + 平移」图案一律命名为归纳头。许多头会看最近 token，图案相似、算法不同。命名应绑定：是否完成 <code>[A][B]…[A]→[B]</code>、消融是否选择性地破坏该任务、以及是否与训练拐点同期出现。图案是筛子，不是定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归纳头用 QK 找到「上一次当前 token 出现之处的后继」，用 OV 把该后继拷到现在。</li><li>最小实现常需前一 token 头与归纳头两层配合。</li><li>Olsson 等人用六条证据论证：它们可能是宽定义下大部分 in-context learning 的机制来源。</li><li>两层注意力模型上有因果；带 MLP 的大模型上以相关为主，假说强度下降。</li><li>模糊匹配把精确复制接到 few-shot 类比，但仍不是多步推理的充分机制。</li><li>出处：Olsson et al., <em>In-context Learning and Induction Heads</em>, Anthropic, 2022, arXiv:2209.11895；电路语言见 Elhage et al., <em>A Mathematical Framework for Transformer Circuits</em>, 2021。</li></ul>',9))])}const P=A(c,[["render",h]]);export{C as __pageData,P as default};
